class Solution {
public:
    bool isPossible(int n, std::vector<std::vector<int>>& edges) {
        std::vector<std::unordered_set<int>> adj(n + 1);
        for (const auto& e : edges) {
            adj[e[0]].insert(e[1]);
            adj[e[1]].insert(e[0]);
        }
        std::vector<int> odds;
        for (int i = 1; i <= n; ++i) {
            if (adj[i].size() % 2 == 1) odds.push_back(i);
        }
        if (odds.empty()) return true;
        if (odds.size() == 2) {
            int a = odds[0], b = odds[1];
            if (!adj[a].count(b)) return true;
            for (int c = 1; c <= n; ++c) {
                if (c != a && c != b && !adj[a].count(c) && !adj[b].count(c)) return true;
            }
            return false;
        }
        if (odds.size() == 4) {
            int a = odds[0], b = odds[1], c = odds[2], d = odds[3];
            if (!adj[a].count(b) && !adj[c].count(d)) return true;
            if (!adj[a].count(c) && !adj[b].count(d)) return true;
            if (!adj[a].count(d) && !adj[b].count(c)) return true;
            return false;
        }
        return false;
    }
};

class Solution {
    public boolean isPossible(int n, java.util.List<java.util.List<Integer>> edges) {
        java.util.Set<Integer>[] adj = new java.util.HashSet[n + 1];
        for (int i = 0; i <= n; i++) adj[i] = new java.util.HashSet<>();
        for (java.util.List<Integer> e : edges) {
            int u = e.get(0), v = e.get(1);
            adj[u].add(v);
            adj[v].add(u);
        }
        java.util.List<Integer> odds = new java.util.ArrayList<>();
        for (int i = 1; i <= n; i++) {
            if (adj[i].size() % 2 == 1) odds.add(i);
        }
        if (odds.isEmpty()) return true;
        if (odds.size() == 2) {
            int a = odds.get(0), b = odds.get(1);
            if (!adj[a].contains(b)) return true;
            for (int c = 1; c <= n; c++) {
                if (c != a && c != b && !adj[a].contains(c) && !adj[b].contains(c)) return true;
            }
            return false;
        }
        if (odds.size() == 4) {
            int a = odds.get(0), b = odds.get(1), c = odds.get(2), d = odds.get(3);
            if (!adj[a].contains(b) && !adj[c].contains(d)) return true;
            if (!adj[a].contains(c) && !adj[b].contains(d)) return true;
            if (!adj[a].contains(d) && !adj[b].contains(c)) return true;
            return false;
        }
        return false;
    }
}

var isPossible = function(n, edges) {
    const adj = Array.from({ length: n + 1 }, () => new Set());
    for (const [u, v] of edges) {
        adj[u].add(v);
        adj[v].add(u);
    }
    const odds = [];
    for (let i = 1; i <= n; i++) {
        if (adj[i].size % 2 === 1) odds.push(i);
    }
    if (odds.length === 0) return true;
    if (odds.length === 2) {
        const [a, b] = odds;
        if (!adj[a].has(b)) return true;
        for (let c = 1; c <= n; c++) {
            if (c !== a && c !== b && !adj[a].has(c) && !adj[b].has(c)) return true;
        }
        return false;
    }
    if (odds.length === 4) {
        const [a, b, c, d] = odds;
        if (!adj[a].has(b) && !adj[c].has(d)) return true;
        if (!adj[a].has(c) && !adj[b].has(d)) return true;
        if (!adj[a].has(d) && !adj[b].has(c)) return true;
        return false;
    }
    return false;
};
